<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Verifikasi {{ $document->document_number }}</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 20% 0,#d8fff1 0,transparent 38%),#061914;color:#e7fff6;font:14px/1.6 Arial,sans-serif}.wrap{max-width:760px;margin:auto;padding:48px 20px}.brand{font-size:13px;font-weight:800;letter-spacing:2px;color:#5ee9bd}.card{position:relative;margin-top:25px;overflow:hidden;border:1px solid rgba(255,255,255,.12);border-radius:24px;background:rgba(255,255,255,.07);padding:32px;box-shadow:0 30px 90px rgba(0,0,0,.25);backdrop-filter:blur(12px)}.orb{position:absolute;right:-80px;top:-90px;width:220px;height:220px;border-radius:50%;background:#15c68d;filter:blur(70px);opacity:.18}.status{display:inline-block;border-radius:999px;padding:8px 13px;font-size:11px;font-weight:800;letter-spacing:1px}.valid{background:#5ee9bd;color:#052219}.invalid{background:#ff6b8a;color:#310913}h1{margin:20px 0 4px;font-size:28px}p{color:#a7c7bd}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:25px}.item{border:1px solid rgba(255,255,255,.09);border-radius:14px;background:rgba(0,0,0,.12);padding:14px}.item small{display:block;color:#71968a;font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase}.item strong{display:block;margin-top:5px;color:#fff}.warning{margin-top:20px;border-left:3px solid #ff6b8a;background:rgba(255,107,138,.1);padding:12px 15px;color:#ffd5de}.footer{margin-top:22px;color:#69897f;font-size:11px;text-align:center}@media(max-width:560px){.grid{grid-template-columns:1fr}.card{padding:24px}h1{font-size:23px}}</style></head><body><main class="wrap"><div class="brand">SIAKAD · DIGITAL TRUST</div><section class="card"><div class="orb"></div><span class="status {{ $valid ? 'valid':'invalid' }}">{{ $valid ? '✓ DOKUMEN VALID':'! DOKUMEN TIDAK VALID' }}</span><h1>{{ $typeLabel }}</h1><p>Hasil pemeriksaan registri resmi {{ $document->snapshot['institution']['name'] }}.</p><div class="grid"><div class="item"><small>Nomor dokumen</small><strong>{{ $document->document_number }}</strong></div><div class="item"><small>Diterbitkan</small><strong>{{ $document->issued_at->locale('id')->translatedFormat('d F Y, H:i') }} WIB</strong></div><div class="item"><small>Pemilik</small><strong>{{ $document->snapshot['student']['name'] }}</strong></div><div class="item"><small>NIM</small><strong>{{ $document->snapshot['student']['nim'] }}</strong></div><div class="item"><small>Program studi</small><strong>{{ $document->snapshot['student']['program'] }}</strong></div><div class="item"><small>Penerbit</small><strong>{{ $document->issuer?->name }}</strong></div></div>@if($document->revoked_at)<div class="warning"><strong>Dokumen dicabut pada {{ $document->revoked_at->locale('id')->translatedFormat('d F Y, H:i') }} WIB.</strong><br>{{ $document->revocation_reason }}</div>@elseif(!$integrityValid)<div class="warning"><strong>Integritas snapshot dokumen tidak cocok.</strong> Hubungi administrator institusi.</div>@endif</section><div class="footer">Kode verifikasi {{ $document->verification_code }} · Pemeriksaan hash SHA-256 dan status pencabutan dilakukan langsung dari registri.</div></main></body></html>
